// API Jinx UI предполагается по конвенции (Modal с open/onClose/title, Button с variant); при расхождении с реальными экспортами @jinx-ui/react имена нужно сверить с докой.
import { useCallback, useState } from 'react';
import { Button, Modal, Stack, Text } from '@jinx-ui/react';

type DeleteProjectButtonProps = {
  onConfirm: () => void;
  projectName?: string;
};

export default function DeleteProjectButton({ onConfirm, projectName }: DeleteProjectButtonProps) {
  const [isOpen, setIsOpen] = useState(false);

  const close = useCallback(() => setIsOpen(false), []);

  const handleConfirm = useCallback(() => {
    setIsOpen(false);
    onConfirm();
  }, [onConfirm]);

  return (
    <>
      <Button variant="danger" onClick={() => setIsOpen(true)}>
        Удалить проект
      </Button>

      <Modal open={isOpen} onClose={close} title="Удалить проект?">
        <Stack direction="column" gap="var(--jx-space-4)">
          <Text>
            {projectName
              ? `Проект «${projectName}» будет удалён безвозвратно.`
              : 'Проект будет удалён безвозвратно.'}{' '}
            Это действие необратимо: восстановить данные будет невозможно.
          </Text>

          <Stack direction="row" gap="var(--jx-space-2)" justify="end">
            <Button variant="secondary" onClick={close}>
              Отмена
            </Button>
            <Button variant="danger" onClick={handleConfirm}>
              Удалить
            </Button>
          </Stack>
        </Stack>
      </Modal>
    </>
  );
}

